class CustomVideoPlayer extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"}),this.shadowRoot.innerHTML=`<style>:host{display:block;width:800px;max-width:100%;font-family:system-ui,sans-serif}.player{position:relative}video{width:100%;border-radius:8px;background:#000}.controls{display:flex;align-items:center;gap:10px;background:rgba(0,0,0,.6);padding:10px;border-radius:0 0 8px 8px;position:absolute;bottom:0;width:100%;box-sizing:border-box;backdrop-filter:blur(8px)}button,input[type=range]{cursor:pointer}button{background:none;border:none;color:#fff;font-size:20px;transition:transform .1s}button:hover{transform:scale(1.2)}input[type=range]{flex:1;accent-color:#09f}.progress-container{position:relative;flex:1}.buffered,.buffer-fill{position:absolute;height:4px;top:50%;transform:translateY(-50%);border-radius:2px}.buffered{background:#444;width:100%}.buffer-fill{background:#666;width:0%}.thumb-preview{position:absolute;bottom:40px;left:0;background:rgba(0,0,0,.8);color:#fff;font-size:12px;padding:4px 6px;border-radius:4px;transform:translateX(-50%);display:none;pointer-events:none}</style><div class="player"><video id="video" preload="metadata"></video><div class="controls"><button id="playpause">▶️</button><div class="progress-container"><div class="buffered"></div><div class="buffer-fill" id="buffer-fill"></div><input id="progress" type="range" value="0" min="0" max="100"><div class="thumb-preview" id="thumb-preview">00:00</div></div><input id="volume" type="range" value="100" min="0" max="100" style="width:100px;"><button id="fullscreen">⛶</button></div></div>`}connectedCallback(){const e=this.shadowRoot.getElementById("video"),t=this.shadowRoot.getElementById("playpause"),n=this.shadowRoot.getElementById("progress"),i=this.shadowRoot.getElementById("buffer-fill"),o=this.shadowRoot.getElementById("volume"),s=this.shadowRoot.getElementById("fullscreen"),l=this.shadowRoot.getElementById("thumb-preview");e.src=this.getAttribute("src")||"https://www.w3schools.com/html/mov_bbb.mp4";const r=()=>{e.paused?(e.play(),t.textContent="⏸️"):(e.pause(),t.textContent="▶️")};t.addEventListener("click",r),e.addEventListener("click",r),e.addEventListener("timeupdate",()=>{n.value=e.currentTime/e.duration*100}),n.addEventListener("input",()=>{e.currentTime=n.value/100*e.duration}),e.addEventListener("progress",()=>{if(e.buffered.length>0){const t=e.buffered.end(e.buffered.length-1)/e.duration*100;i.style.width=t+"%"}}),o.addEventListener("input",()=>{e.volume=o.value/100}),s.addEventListener("click",()=>{document.fullscreenElement?document.exitFullscreen():e.requestFullscreen()}),n.addEventListener("mousemove",t=>{const i=n.getBoundingClientRect(),o=(t.clientX-i.left)/i.width,s=o*e.duration;l.style.left=t.clientX-i.left+"px",l.textContent=this.formatTime(s),l.style.display="block"}),n.addEventListener("mouseleave",()=>l.style.display="none"),document.addEventListener("keydown",t=>{switch(t.code){case"Space":t.preventDefault(),r();break;case"ArrowRight":e.currentTime+=5;break;case"ArrowLeft":e.currentTime-=5;break;case"ArrowUp":e.volume=Math.min(e.volume+.1,1),o.value=100*e.volume;break;case"ArrowDown":e.volume=Math.max(e.volume-.1,0),o.value=100*e.volume;break;case"KeyF":s.click()}})}formatTime(e){if(isNaN(e))return"00:00";const t=Math.floor(e/60).toString().padStart(2,"0"),n=Math.floor(e%60).toString().padStart(2,"0");return`${t}:${n}`}}customElements.define("custom-video-player",CustomVideoPlayer);
